package com.codenamecoraline.entity.firedragon;

/** Visual-only clip metadata; generated by tools/generate_fire_dragon_animations.py. */
public enum FireDragonAnimation {
    NONE(1, false),
    BREATHE(40, true),
    IDLE_SNIFF(30, false),
    IDLE_WINGS(36, false),
    IDLE_TAIL(40, false),
    WALK(20, true),
    FLY(16, true),
    TAKEOFF(16, false),
    LAND(16, false),
    FIRE_WINDUP(12, false),
    FIRE_RELEASE(1, false),
    FIRE_RECOVERY(15, false),
    HURT(8, false),
    STUN(20, false),
    DEATH(20, false),
    SIT(12, false),
    STAND(12, false),
    SHOULDER(40, true),
    EAT(24, false),
    PLAY_CHASE(100, true),
    GREET(30, false),
    IMITATE_WINGS(40, false),
    REST_TOGETHER(100, false);
    public final int ticks;
    public final boolean looping;
    FireDragonAnimation(int ticks, boolean looping) { this.ticks = ticks; this.looping = looping; }
    public static FireDragonAnimation fromName(String name) {
        for (FireDragonAnimation clip : values()) if (clip.name().equalsIgnoreCase(name)) return clip;
        return NONE;
    }
}
